# 掷骰子统计探索台
n = 120   # 掷的次数

hide()
c1 = 0
c2 = 0
c3 = 0
c4 = 0
c5 = 0
c6 = 0
i = 0
while i < n:
    f = random(1, 6)
    if f == 1:
        c1 = c1 + 1
    if f == 2:
        c2 = c2 + 1
    if f == 3:
        c3 = c3 + 1
    if f == 4:
        c4 = c4 + 1
    if f == 5:
        c5 = c5 + 1
    if f == 6:
        c6 = c6 + 1
    i = i + 1
i = 1
while i < 7:
    if i == 1:
        cnt = c1
    if i == 2:
        cnt = c2
    if i == 3:
        cnt = c3
    if i == 4:
        cnt = c4
    if i == 5:
        cnt = c5
    if i == 6:
        cnt = c6
    x = -170 + i * 52
    h = cnt * 260 / n
    if h < 4:
        h = 4
    col = "#3b82f6"
    if i == 6:
        col = "#f59e0b"
    fill_rect(x + 16, -100 + h / 2, 30, h, col)
    write(i, x + 16, -120, "#dc2626", 13)
    write(cnt, x + 16, -100 + h + 15, "#1d4ed8", 11)
    i = i + 1
fill_rect(0, -112, 440, 6, "#94a3b8")
write("掷 " + n + " 次：六个面谁多谁少？", -190, 155, "#0f172a", 12)
write("橙色=6 点。掷得越多，六根柱子越整齐！", -190, -150, "#16a34a", 11)
